Let $c \in \mathbb{Z}_+$, $a, b, \lambda \in \mathbb{Z}/c\mathbb{Z}$, $0 < X,Y \ll c$, and $I, J \subset \mathbb{R}$ be intervals of lengths $|I| = X$, $|J| = Y$. Then for any $\varepsilon > 0$ and any $(c\alpha, c\beta) \in I \times J$, one has
\begin{equation} 
    \# \left\{
    (x, y) \in (I \cap \mathbb{Z}) \times (J \cap \mathbb{Z}) : xy \equiv \lambda \ (\textnormal{mod } c)
    \right\}
    \ll_\varepsilon 
    c^\varepsilon \left(\frac{XY}{c}\, T_{\frac{c}{X}, \frac{c}{Y}}\left(\alpha, \beta\right) + \gcd(\lambda, c)\right),
\end{equation}
with $T_{M,N}(\alpha, \beta)$ as in 5.

Let $\varepsilon > 0$, $X, A > 0$, $N \ge 1/2$, $q, a \in \mathbb{Z}_+$, and $(a_n)_{n \sim N}$ be a complex sequence. Let $f : (0, 4) \to \mathbb{C}$ be a smooth function with $f^{(j)} \ll_j 1$ for $j \ge 0$, and $\mu$ be a bounded-variation complex Borel measure on $\mathbb{R}/\mathbb{Z}$, such that\footnote{We slightly abuse notation in this section: the measure $\mu$ should not be confused with the cusp parameter $\mu(\mathfrak{a}) = q^{-1}$, and the scalar $a$ should not be confused with the sequence $(a_n)$.}
\[
    a_n = f\left(\frac{n}{N}\right) \check{\mu}\left(n\right),
\]
for all $n \sim N$ (in particular, one can take $f \equiv 1$, $d\mu = \widehat{a}\, d\lambda$). Let $\mathfrak{a}, \rho_{j\mathfrak{a}}(n), \lambda_j,\theta_j$ be as in A, with $\mu(\mathfrak{a}) = q^{-1}$ and the choice of scaling matrix $\sigma_{\mathfrak{a}}$ in 3.9. Then one has
\begin{equation} 
    \sum_{\lambda_j < 1/4}
    X^{\theta_j} 
    \left\vert 
    \sum_{n \sim N} a_n\, \rho_{j\mathfrak{a}}(an)
    \right\vert^2 
    \ll_\varepsilon 
    (qaNX)^{2\varepsilon}
    \left(1 + \frac{aN}{q}\right) A^2,
\end{equation}
whenever
\begin{equation} 
    A \gg \|a_n\|_2 + \frac{\sqrt{\gcd(a, q)} N}{\sqrt{q+aN}} |\mu|(\mathbb{R}/\mathbb{Z}),
    \qquad\qquad
    X \ll \max\left(1, \frac{q}{aN}\right) \max\left(1, \frac{A^2}{\mathcal{I}_N(\mu)}\right).
\end{equation}

Let $\varepsilon, X > 0$, $N \ge 1/2$, $\alpha \in \mathbb{R}/\mathbb{Z}$, and $q, a \in \mathbb{Z}_+$. Then with the notation of A and the choice of scaling matrix in 3.9, the bound
\begin{equation} 
    \sum_{\lambda_j < 1/4}
    X^{\theta_j} 
    \left\vert 
    \sum_{n \sim N} e(n\alpha)\, \rho_{j\mathfrak{a}}(an)
    \right\vert^2 
    \ll_\varepsilon 
    (qaN)^\varepsilon
    \left(1 + \frac{aN}{q}\right) N
\end{equation}
holds for all
\begin{equation} 
        X \ll \frac{\max\left(N, \frac{q}{a}\right)}{\min_{t \in \mathbb{Z}_+} \left(t + N\|t\alpha\| \right)}.
\end{equation}
In particular, this implies the range $X \ll \max(\sqrt{N}, \tfrac{q}{a\sqrt{N}})$, uniformly in $\alpha$ and $\sigma_{\mathfrak{a}}$.
The same result holds if $e(n\alpha)$ is multiplied by $\Phi(n/N)$, for any smooth function  $\Phi : (0, 4) \to \mathbb{C}$ with $\Phi^{(j)} \ll_j 1$.

Let $\varepsilon, X > 0$, $N \ge 1/2$, $L, H \gg 1$, $\alpha_1, \alpha_2 \in \mathbb{R}/\mathbb{Z}$, and $q, a, \ell_1, \ell_2 \in \mathbb{Z}_+$ satisfy $\ell_1, \ell_2 \asymp L$, $(\ell_1, \ell_2) = 1$. Consider the sequence $(a_n)_{n \sim N}$ given by
\[
    a_n := \sum_{\substack{h_1, h_2 \in \mathbb{Z} \\ h_1 \ell_1 - h_2 \ell_2 = n}} \Phi_1\left(\frac{h_1}{H}\right) \Phi_2\left(\frac{h_2}{H}\right) e(h_1 \alpha_1 + h_2 \alpha_2),
\]
where $\Phi_i(t) : (0, \infty) \to \mathbb{C}$ are smooth functions supported in $t \ll 1$, with $\Phi_i^{(j)} \ll_j 1$ for all $j \ge 0$. Then with the notation of A and the choice of scaling matrix in 3.9, if $q \gg L^2$, one has
\begin{equation} 
    \sum_{\lambda_j < 1/4}
    X^{\theta_j} 
    \left\vert 
    \sum_{n \sim N} a_n\, \rho_{j\mathfrak{a}}(an)
    \right\vert^2 
    \ll_\varepsilon 
    (qaH)^{\varepsilon}
    \left(1 + \frac{aN}{q}\right)
    \left(\|a_n\|_2^2 + \gcd(a, q) N \left(\frac{H}{L} + \frac{H^2}{L^2}\right)\right),
\end{equation}
whenever 
\begin{equation} 
    X \ll \max\left(1, \frac{q}{aN}\right) \max\left(1, \frac{NH}{(H+L)LM}\right),
    \qquad\quad 
    M := \min_{\substack{t \in \mathbb{Z}_+ \\ i \in \{1, 2\}}} \left(t + H \|t\alpha_i\|\right).
\end{equation}

Let $(q, N, Z, (a_n)_{n \sim N}, Y_N, A_N)$ satisfy 14. Let $\varepsilon > 0$, $C \gg 1$, $m \in \mathbb{Z}_+$, and $\mathfrak{a}, \mathfrak{b}$ be cusps of $\Gamma_0(q)$, with $\mu(\mathfrak{a}) = \mu(\mathfrak{b}) = q^{-1}$ and $\sigma_{\mathfrak{b}}$ as in 3.9. Let $\Phi : (0, \infty)^2 \to \mathbb{C}$ be a smooth function, with $\Phi(x, y)$ supported in $x, y \asymp 1$, and $\partial_x^j \partial_y^k \Phi(x, y) \ll_{j,k,\varepsilon} Z^{j\varepsilon}$ for $j, k \ge 0$. Then with a consistent choice of the $\pm$ sign, one has
\begin{equation} 
\begin{aligned}
    \sum_{n \sim N} a_n
    \sum_{c \in \mathcal{C}_{\mathfrak{a}\mathfrak{b}}} \Phi\left(\frac{n}{N}, \frac{c}{C}\right) S_{\mathfrak{a}\mathfrak{b}}(m, \pm n; c)
    \ll_\varepsilon
    (qmNCZ)^{O(\varepsilon)}
    \left(1 + T\right)^{\theta(q)}
    \frac{C^2 A_N}{C + \sqrt{mN}} 
    \\
    \times 
    \left(1 + \frac{mN}{C^2} +\frac{\sqrt{(q,m)m}}{q} \right)^{1/2}
    \left(1 + \frac{mN}{C^2} + \frac{N}{q}\right)^{1/2}
    ,
\end{aligned}
\end{equation}
for
\[
    T = \frac{T_0}{\sqrt{Y_N}}, 
    \qquad\qquad 
    T_0 := \frac{C}{\max\left(m, q^2 (q, m)^{-1} \right)^{1/2}\max\left(N, q\right)^{1/2}}
    \le
    \frac{C}{q^{3/2} (q,m)^{-1/2}}.
\]

Let $(q, M, Z, (a_m)_{m \sim M}, Y_M, A_M)$ and $(q, N, Z, (b_n)_{n \sim N}, Y_N, A_N)$ satisfy 14. Let $\varepsilon > 0$, $C \gg 1$, $m \in \mathbb{Z}_+$, and $\mathfrak{a}, \mathfrak{b}$ be cusps of $\Gamma_0(q)$, with $\mu(\mathfrak{a}) = \mu(\mathfrak{b}) = q^{-1}$ and $\sigma_{\mathfrak{a}}, \sigma_{\mathfrak{b}}$ as in 3.9. Let $\Phi : (0, \infty)^3 \to \mathbb{C}$ be a smooth function, with $\Phi(x, y, z)$ supported in $x, y, z \asymp 1$, and $\partial_x^j \partial_y^k \partial_z^\ell \Phi(x, y, z) \ll_{j,k,\ell,\varepsilon} Z^{(j+k)\varepsilon}$ for $j, k, \ell \ge 0$. Then with a consistent choice of the $\pm$ sign, one has 
\begin{equation} 
\begin{aligned}
    \sum_{m \sim M} a_m
    \sum_{n \sim N} b_n
    \sum_{c \in \mathcal{C}_{\mathfrak{a}\mathfrak{b}}} \Phi\left(\frac{m}{M}, \frac{n}{N}, \frac{c}{C}\right) S_{\mathfrak{a}\mathfrak{b}}(m, \pm n; c)
    \ll_\varepsilon
    (qMNCZ)^{O(\varepsilon)}
    \left(1 + T\right)^{\theta(q)}
    \\
    \times 
    \frac{C^2 A_M A_N}{C + \sqrt{MN}} 
    \left(1 + \frac{MN}{C^2} + \frac{M}{q} \right)^{1/2}
    \left(1 + \frac{MN}{C^2} + \frac{N}{q}\right)^{1/2},
\end{aligned}
\end{equation}
for
\[
    T = \frac{T_0}{\sqrt{Y_M Y_N}}, 
    \qquad\qquad 
    T_0 := \frac{C}{\max\left(M, q \right)^{1/2}\max\left(N, q\right)^{1/2}}
    \le
    \frac{C}{q}.
\]
In particular, for relatively prime positive integers $r, s$ with $rs = q$, one has
\begin{equation} 
\begin{aligned}
    \sum_{m \sim M} a_m
    \sum_{n \sim N} b_n
    \sum_{(c, r) = 1} \Phi\left(\frac{m}{M}, \frac{n}{N}, \frac{c}{C}\right) S(m\overline{r}, \pm n; sc)
    \ll_\varepsilon
    (rsMNCZ)^{O(\varepsilon)} \left(1 + \frac{C}{\sqrt{r Y_M Y_N}} \right)^{\theta(q)}
    \\
    \times
    A_M A_N
    \frac{\left(s\sqrt{r}C + \sqrt{MN} + \sqrt{sM} C\right)\left(s\sqrt{r}C + \sqrt{MN} + \sqrt{sN} C\right)}{s\sqrt{r}C + \sqrt{MN}}.
\end{aligned}
\end{equation}

Let $Q, M, N \ge 1/2$, $C, Z \gg 1$, $Y_N > 0$, $\varepsilon > 0$, and $\omega \in \mathbb{R}/\mathbb{Z}$. For each $q \sim Q$, let $(q, N, Z, (a_{n,q})_{n \sim N}, Y_N, A_{N,q})$ satisfy 14, $w_q \in \mathbb{C}$, $\mathfrak{b}_q$ be a cusp of $\Gamma_0(q)$, and $\Phi_q : (0, \infty)^3 \to \mathbb{C}$ be a smooth function, with $\Phi_q(x, y, z)$ supported in $x, y, z \asymp 1$, and $\partial_x^j \partial_y^k \partial_z^\ell \Phi_q(x, y, z) \ll_{j,k,\ell,\varepsilon} Z^{(j+k)\varepsilon}$ for $j, k, \ell \ge 0$. Then with the choice of scaling matrices in 3.9 and a consistent choice of the $\pm$ sign, one has
\begin{equation} 
\begin{aligned}
    \sum_{q \sim Q} w_q
    \sum_{m \sim M} e(m\omega)
    \sum_{n \sim N} a_{n,q}
    \sum_{c \in \mathcal{C}_{\infty\mathfrak{b}_q}} \Phi_q\left(\frac{m}{M}, \frac{n}{N}, \frac{c}{C}\right) S_{\infty\mathfrak{b}_q}(m, \pm n; c)
    \ll_\varepsilon
    (QMNCZ)^{O(\varepsilon)}
    \\
    \times 
    \left(1 + T\right)^{\theta_{\max}}
    \frac{\sqrt{QM} \|w_q A_{N,q}\|_2 C^2}{C + \sqrt{MN}} 
    \left(1 + \frac{MN}{C^2} + \frac{M}{Q} \right)^{1/2}
    \left(1 + \frac{MN}{C^2} + \frac{N}{Q}\right)^{1/2},
\end{aligned}
\end{equation}
for
\[
    T = \frac{T_0}{\sqrt{Y_N}}, 
    \qquad\qquad 
    T_0 := \frac{C}{\max\left(M, Q \right) \max\left(N, Q\right)^{1/2}}
    \le
    \frac{C}{Q^{3/2}}.
\]
In particular, let $R, S \ge 1/2$; for every $r \sim R, s \sim S$ with $(r, s) = 1$, let $w_{r,s} \in \mathbb{C}$, $\Phi_{r,s}$ be as above, and $(rs, N, Z, (a_{n,r,s})_{n \sim N}, Y_N, A_{N,r,s})$ satisfy 14. Then one has 
\begin{equation} 
\begin{aligned}
    \sum_{\substack{r \sim R \\ s \sim S \\ (r, s) = 1}} w_{r,s} \sum_{m \sim M} e(m\omega)
    \sum_{n \sim N} a_{n,r,s}
    \sum_{(c, r) = 1} \Phi_{r,s}\left(\frac{m}{M}, \frac{n}{N}, \frac{c}{C}\right) S(m\overline{r}, \pm n; sc)
    \ll_\varepsilon
    (RSMNCZ)^{O(\varepsilon)}
    \\
    \times 
    \left(1 + \frac{C}{R \sqrt{S Y_N}}\right)^{\theta_{\max}} 
    \sqrt{RSM} \|w_{r,s} A_{N,r,s}\|_2
    \\
    \times
    \frac{\left(S\sqrt{R}C + \sqrt{MN} + \sqrt{SM} C\right)\left(S\sqrt{R}C + \sqrt{MN} + \sqrt{SN} C\right)}{S\sqrt{R}C + \sqrt{MN}}.
\end{aligned}
\end{equation}

Let $R, S, N \ge 1/2$, $C, D, Z \gg 1$, $Y_N > 0$, and $\varepsilon > 0$. For each $r \sim R, s \sim S$ with $\gcd(r, s) = 1$, let the tuple $(rs, N, Z, (a_{n,r,s})_{n \sim N}, Y_N, A_{N,r,s})$ satisfy 14, $w_{r,s} \in \mathbb{C}$, and $\Phi_{r,s} : (0, \infty)^3 \to \mathbb{C}$ be a smooth function, with $\Phi_{r,s}(x, y, z)$ supported in $x, y, z \asymp 1$, and $\partial_x^j \partial_y^k \partial_z^\ell \Phi_q(x, y, z) \ll_{j,k,\ell,\varepsilon} Z^{j\varepsilon}$ for $j, k, \ell \ge 0$. Then with a consistent choice of the $\pm$ sign, one has
\begin{equation} 
    \sum_{\substack{r \sim R \\ s \sim S \\ (r, s) = 1}} w_{r,s}
    \sum_{n \sim N} a_{n,r,s}
    \sum_{\substack{c, d \\ (rd, sc) = 1}} \Phi_{r,s}\left(\frac{n}{N}, \frac{d}{D}, \frac{c}{C}\right) e\left(\pm n \frac{\overline{rd}}{sc}\right)
    \ll_\varepsilon 
    (RSNCDZ)^{O(\varepsilon)}\, \|w_{r,s} A_{N,r,s}\|_2 \mathscr{I},
\end{equation}
where
\[
    \mathscr{I}^2 := D^2 NR
    +
    \left(1 + \frac{C^2}{R^2 S Y_N}\right)^{\theta_{\max}} 
    CS(C + DR)(RS + N).
\]
